func newPosting() unsafe.Pointer { return unsafe.Pointer(new(carriercapacity.Posting)) }

func newNPosting(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]carriercapacity.Posting, n)))
}

func ptrPosting(p unsafe.Pointer, c int32) any {
	r := (*carriercapacity.Posting)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.CarrierID))
	case 4:
		return (**string)(unsafe.Pointer(&r.OriginLocationID))
	case 5:
		return (**string)(unsafe.Pointer(&r.OriginStateID))
	case 6:
		return (**int64)(unsafe.Pointer(&r.OriginRadiusMiles))
	case 7:
		return (**string)(unsafe.Pointer(&r.DestinationStateID))
	case 8:
		return (**string)(unsafe.Pointer(&r.EquipmentTypeID))
	case 9:
		return &r.AvailableFrom
	case 10:
		return &r.AvailableTo
	case 11:
		return (*int64)(unsafe.Pointer(&r.TruckCount))
	case 12:
		return (*string)(unsafe.Pointer(&r.RateMethod))
	case 13:
		return &r.Rate
	case 14:
		return (*string)(unsafe.Pointer(&r.Source))
	case 15:
		return &r.Notes
	case 16:
		return &r.SearchVector
	case 17:
		return &r.Rank
	case 18:
		return &r.Version
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valuePosting(p unsafe.Pointer, c int32) any {
	r := (*carriercapacity.Posting)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.CarrierID)
	case 4:
		if r.OriginLocationID == nil {
			return nil
		}
		return string(*r.OriginLocationID)
	case 5:
		if r.OriginStateID == nil {
			return nil
		}
		return string(*r.OriginStateID)
	case 6:
		if r.OriginRadiusMiles == nil {
			return nil
		}
		return int64(*r.OriginRadiusMiles)
	case 7:
		if r.DestinationStateID == nil {
			return nil
		}
		return string(*r.DestinationStateID)
	case 8:
		if r.EquipmentTypeID == nil {
			return nil
		}
		return string(*r.EquipmentTypeID)
	case 9:
		return r.AvailableFrom
	case 10:
		return r.AvailableTo
	case 11:
		return int64(r.TruckCount)
	case 12:
		return string(r.RateMethod)
	case 13:
		return r.Rate
	case 14:
		return string(r.Source)
	case 15:
		if r.Notes == "" {
			return nil
		}
		return r.Notes
	case 16:
		return r.SearchVector
	case 17:
		return r.Rank
	case 18:
		return r.Version
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

func attachPosting(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*carriercapacity.Posting)(p)
	switch rel {
	case 0:
		r.Carrier = (*carrier.Carrier)(child)
	case 1:
		r.OriginLocation = (*location.Location)(child)
	case 2:
		r.OriginState = (*usstate.UsState)(child)
	case 3:
		r.DestinationState = (*usstate.UsState)(child)
	case 4:
		r.EquipmentType = (*equipmenttype.EquipmentType)(child)
	}
}

func beforeCreatePosting(ctx context.Context, p unsafe.Pointer) error {
	return (*carriercapacity.Posting)(p).BeforeCreate(ctx)
}

func init() {
	postingsTable.Relations[0].Target = carrierdb.CarriersSchema()
	postingsTable.Relations[1].Target = locationdb.LocationsSchema()
	postingsTable.Relations[2].Target = usstatedb.UsStatesSchema()
	postingsTable.Relations[3].Target = usstatedb.UsStatesSchema()
	postingsTable.Relations[4].Target = equipmenttypedb.EquipmentTypesSchema()
}

